import{c as a,Q as e,j as l,m as n}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"SetQuantScalar","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetQuantScalar","slug":"setquantscalar"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/SetQuantScalar.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/SetQuantScalar.md"}'),s={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/SetQuantScalar.md"};function r(_,t,i,p,o,d){return e(),l("div",null,[...t[0]||(t[0]=[n(`<h1 id="setquantscalar" tabindex="-1">SetQuantScalar <a class="header-anchor" href="#setquantscalar" aria-label="Permalink to &quot;SetQuantScalar&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>本接口提供对输出矩阵的所有值采用同一系数进行量化或反量化的功能，即整个C矩阵对应一个量化参数，量化参数的shape为[1]。</p><p>Matmul反量化场景：在Matmul计算时，左、右矩阵的输入为int8_t或int4b_t类型，输出为half类型；或者左、右矩阵的输入为int8_t类型，输出为int8_t类型。该场景下，输出C矩阵的数据从CO1搬出到Global Memory时，会执行反量化操作，将最终结果反量化为对应的half或int8_t类型。</p><p>Matmul量化场景：在Matmul计算时，左、右矩阵的输入为half或bfloat16_t类型，输出为int8_t类型。该场景下，输出C矩阵的数据从CO1搬出到Global Memory时，会执行量化操作，将最终结果量化为int8_t类型。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void SetQuantScalar(const uint64_t quantScalar)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>quantScalar</td><td>输入</td><td>量化或反量化系数。</td></tr></tbody></table><p>将float数据类型的量化计算参数scale、offset转换为uint64类型的入参的计算公式如下：</p><ol><li><p>quantScalar为64位格式，初始为0。</p></li><li><p>scale按bit位取高19位截断，存储于quantScalar的bit位32位处，并将46位修改为1。</p><p><em>quantScalar = quantScalar∣ (<strong>s__c__a__l__e</strong> &amp; 0__x__F__F__F__F__E__000) ∣ (1 &lt;&lt; 46)</em></p></li><li><p>根据offset取值进行后续计算：</p><ul><li>若offset不存在，不再进行后续计算。</li><li>若offset存在： <ol><li><p>将offset值处理为int，范围为[-256, 255]。</p><p>_o__f__f__s__e__t _<em>= <strong>M__a__x</strong>(<strong>M__i__n</strong>(<strong>I__N__T</strong>(<strong>R__o__u__n__d</strong>(<strong>o__f__f__s__e__t</strong>)), 255), −256)</em></p></li><li><p>再将offset按bit位保留9位并存储于quantScalar的37到45位。</p><p><em>quantScalar <strong>= (quantScalar &amp; 0__x__4000__F__F__F__F__F__F__F__F</strong>) ∣ ((<strong>o__f__f__s__e__t</strong> &amp; 0__x__1__F__F</em>_) &lt;&lt; 37)_</p></li></ol></li></ul></li></ol><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>需与<a href="./../Matmul-Tiling侧接口/Matmul-Tiling类/SetDequantType.html">SetDequantType</a>保持一致。</p><p>本接口必须在<a href="./Iterate.html">Iterate</a>或者<a href="./IterateAll.html">IterateAll</a>前调用。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);</span></span>
<span class="line"><span>float tmp = 0.1;  // 输出gm时会乘以0.1</span></span>
<span class="line"><span>// 将浮点值的量化或反量化系数，转换为uint64_t类型</span></span>
<span class="line"><span>uint64_t ans = static_cast&lt;uint64_t&gt;(*reinterpret_cast&lt;int32_t*&gt;(&amp;tmp));</span></span>
<span class="line"><span>mm.SetQuantScalar(ans);</span></span>
<span class="line"><span>mm.SetTensorA(gm_a);</span></span>
<span class="line"><span>mm.SetTensorB(gm_b);</span></span>
<span class="line"><span>if (tiling.isBias) {</span></span>
<span class="line"><span>    mm.SetBias(biasGlobal);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>mm.IterateAll(gm_c);</span></span>
<span class="line"><span>mm.End();</span></span></code></pre></div>`,20)])])}const u=a(s,[["render",r]]);export{h as __pageData,u as default};
